script.setup:
// Anime.js choreographs plain JS objects: one createTimeline() of seven acts, each a staggered
// animation over 153 tile objects (position, scale, turn, roundness, ring, hue) with stagger({ grid }).
// The timeline is paused and seeked from the scene clock every frame; WebGL draws the tiles, the easing
// curve of the current act and a progress bar of the timeline.
const anime = await ctx.utils.import("https://esm.sh/animejs@4.5.0");
const { createTimeline, stagger, eases, cubicBezier, steps } = anime;
const COLS = 17, ROWS = 9, N = COLS * ROWS, GAP = 60;

const EASES = [
  ["outElastic(1, .55)", eases.outElastic(1, 0.55)],
  ["inOutExpo", eases.inOutExpo],
  ["outBack(2.2)", eases.outBack(2.2)],
  ["outBounce", eases.outBounce],
  ["inOutCirc", eases.inOutCirc],
  ["cubicBezier(.8, 0, .2, 1)", cubicBezier(0.8, 0, 0.2, 1)],
  ["inOutQuint", eases.inOutQuint],
  ["steps(6)", steps(6)],
  ["linear", eases.linear],
];
const ORIGINS = ["center", "first", "last", "random"];

const gridPos = (i) => ({ x: ((i % COLS) - (COLS - 1) / 2) * GAP, y: ((ROWS - 1) / 2 - Math.floor(i / COLS)) * GAP });
const tiles = Array.from({ length: N }, (_, i) => {
  const g = gridPos(i);
  return { i, gx: g.x, gy: g.y, x: g.x, y: g.y, s: 0, rot: 0, round: 1, ring: 0, hue: 0 };
});
const dist = (t) => Math.hypot(t.gx / (GAP * COLS / 2), t.gy / (GAP * ROWS / 2)) / Math.SQRT2;
const sunflower = (t) => { const a = t.i * 2.39996 + 0.6, r = 29 * Math.sqrt(t.i + 0.6); return { x: Math.cos(a) * r, y: Math.sin(a) * r }; };

// Seven acts. With "Cycle" each act gets its own easing (the index into EASES); otherwise all use the pick.
const ACTS = [
  { name: "Bloom", ease: 0, dur: 1000, gap: 0, params: () => ({ s: [0, 1], rot: [-Math.PI / 2, 0], hue: (t) => dist(t) * 0.55 }) },
  { name: "Turn", ease: 1, dur: 900, gap: 250, params: () => ({ rot: Math.PI / 4, round: 0.18, s: 0.82 }) },
  { name: "Wave", ease: 4, dur: 1100, gap: 150, axis: "x", params: () => ({ y: (t) => t.gy * 0.55 + Math.sin(t.gx / GAP * 0.62) * 150, rot: (t) => Math.PI / 4 + Math.cos(t.gx / GAP * 0.62) * 0.9, s: 0.7, hue: (t) => 0.15 + (t.gx / (GAP * COLS) + 0.5) * 0.85 }) },
  { name: "Spiral", ease: 2, dur: 1300, gap: 250, params: () => ({ x: (t) => sunflower(t).x, y: (t) => sunflower(t).y, s: (t) => 0.35 + (t.i / N) * 0.75, round: 1, rot: 0, hue: (t) => 1 - t.i / N }) },
  { name: "Rings", ease: 5, dur: 900, gap: 300, params: () => ({ ring: 1, s: (t) => 0.5 + (t.i / N) * 1.05, hue: (t) => (1 - t.i / N) * 0.6 + 0.4 }) },
  { name: "Home", ease: 3, dur: 1300, gap: 350, params: () => ({ x: (t) => t.gx, y: (t) => t.gy, s: 0.9, ring: 0, round: 0.5, rot: Math.PI / 2, hue: (t) => dist(t) * 0.55 }) },
  { name: "Fold", ease: 6, dur: 800, gap: 500, params: () => ({ s: 0, rot: Math.PI, round: 1 }) },
];

const s = ctx.state;
Object.assign(s, { anime, createTimeline, stagger, EASES, ORIGINS, ACTS, tiles, N, COLS, ROWS, playhead: 0, key: "", labelKey: "" });

s.build = (easing, origin, staggerMs) => {
  s.tl?.cancel?.();
  for (const t of s.tiles) Object.assign(t, { x: t.gx, y: t.gy, s: 0, rot: 0, round: 1, ring: 0, hue: 0 });
  const from = s.ORIGINS[origin] ?? "center";
  const tl = s.createTimeline({ autoplay: false });
  const acts = [];
  let at = 0;
  for (const act of s.ACTS) {
    at = act.gap ? tl.duration + act.gap : 0;
    const easeIndex = easing > 0 ? easing - 1 : act.ease;
    const delay = s.stagger(staggerMs, { grid: [s.COLS, s.ROWS], from, axis: act.axis, seed: from === "random" ? 7 : undefined });
    tl.add(s.tiles, { ...act.params(), duration: act.dur, ease: s.EASES[easeIndex][1], delay }, at);
    acts.push({ name: act.name, start: at, dur: act.dur, ease: easeIndex });
  }
  s.tl = tl; s.acts = acts; s.total = tl.duration + 700; // a short rest before it loops
  tl.seek(0);
};

// Every instance is a rounded box: center (2), size (2), turn, roundness, ring, rgba (4).
const gl = ctx.gl, FLOATS = 11;
const quad = gl.createBuffer();
gl.bindBuffer(gl.ARRAY_BUFFER, quad);
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
const vao = gl.createVertexArray(), buffer = gl.createBuffer();
gl.bindVertexArray(vao);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
const attr = (loc, n, off) => { gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc, n, gl.FLOAT, false, FLOATS * 4, off * 4); gl.vertexAttribDivisor(loc, 1); };
attr(1, 4, 0); attr(2, 3, 4); attr(3, 4, 7);
gl.bindVertexArray(null);
const program = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_position;
layout(location=1) in vec4 a_box;   // center xy, size wh (frame units)
layout(location=2) in vec3 a_shape; // turn, roundness, ring
layout(location=3) in vec4 a_color;
uniform vec2 u_view;
out vec2 v_local; out vec2 v_half; out vec3 v_shape; out vec4 v_color;
void main() {
  v_half = a_box.zw * 0.5; v_shape = a_shape; v_color = a_color;
  vec2 local = a_position * (v_half + 3.0); // margin for the antialiased edge
  v_local = local;
  float c = cos(a_shape.x), s = sin(a_shape.x);
  vec2 p = a_box.xy + mat2(c, s, -s, c) * local;
  gl_Position = vec4(p / u_view * 2.0, 0.0, 1.0);
}`, `#version 300 es
precision highp float;
in vec2 v_local; in vec2 v_half; in vec3 v_shape; in vec4 v_color;
out vec4 outColor;
void main() {
  float m = min(v_half.x, v_half.y);
  float r = v_shape.y * m;
  vec2 q = abs(v_local) - v_half + r;
  float d = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
  float thick = mix(m * 2.0, m * 0.22, v_shape.z); // ring 0 = solid, 1 = thin outline
  d = max(d, -(d + thick));
  float aa = fwidth(d);
  float a = 1.0 - smoothstep(-aa, aa, d);
  if (a <= 0.0) discard;
  float light = 1.0 + 0.12 * (v_local.y / max(v_half.y, 1.0)); // a soft top light
  outColor = vec4(v_color.rgb * light * v_color.a * a, v_color.a * a);
}`);

// Text (act and easing names) goes through a 2D canvas texture, redrawn only when it changes.
const label = document.createElement("canvas");
const textTex = gl.createTexture();
gl.bindTexture(gl.TEXTURE_2D, textTex);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
const textProgram = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; uniform sampler2D u_text; out vec4 outColor;
void main() { outColor = texture(u_text, vec2(v_uv.x, 1.0 - v_uv.y)); }`);
Object.assign(s, { vao, buffer, program, FLOATS, data: new Float32Array((N + 400) * FLOATS), label, textTex, textProgram });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;

// Rebuild the timeline when the easing, origin or stagger changes; keep the playhead where it was.
const key = `${u.u_easing}|${u.u_origin}|${Math.round(u.u_stagger)}`;
if (key !== s.key) { s.key = key; s.build(u.u_easing, u.u_origin, u.u_stagger); }
if (u.u_replay) s.playhead = 0;
s.playhead += ctx.dt * 1000 * u.u_speed;
if (s.playhead > s.total) s.playhead = 0;
s.tl.seek(Math.min(s.playhead, s.tl.duration));

let actIndex = 0;
s.acts.forEach((a, i) => { if (s.playhead >= a.start) actIndex = i; });
const act = s.acts[actIndex];
const [easeName, easeFn] = s.EASES[act.ease];

// Frame: 1000 units tall, centered on the origin.
const H = 1000, W = H * w / h;
const palette = [u.u_c1, u.u_c2, u.u_c3, u.u_c4, u.u_c1];
const paint = (t) => {
  const x = ((t % 1) + 1) % 1 * 4, k = Math.min(Math.floor(x), 3), f = x - k;
  return [0, 1, 2].map((c) => palette[k][c] + (palette[k + 1][c] - palette[k][c]) * f);
};
const ink = u.u_ink;
let n = 0;
const push = (x, y, bw, bh, rot, round, ring, rgb, alpha) => {
  s.data.set([x, y, bw, bh, rot, round, ring, rgb[0], rgb[1], rgb[2], alpha], n++ * s.FLOATS);
};
for (const t of s.tiles) {
  const size = Math.max(t.s, 0) * 46 * u.u_size;
  if (size > 0.01) push(t.x, t.y + 40, size, size, t.rot, Math.min(Math.max(t.round, 0), 1), Math.min(Math.max(t.ring, 0), 1), paint(t.hue), 1);
}

// The easing curve of the current act, drawn as a dense run of dots, with the leading tile riding it.
const box = 140, left = -W / 2 + 70, bottom = -H / 2 + 70;
push(left + box / 2, bottom, box, 2, 0, 1, 0, ink, 0.16);
push(left + box / 2, bottom + box, box, 2, 0, 1, 0, ink, 0.16);
for (let i = 0; i <= 120; i++) {
  const p = i / 120;
  push(left + p * box, bottom + easeFn(p) * box, 4.5, 4.5, 0, 1, 0, ink, 0.85);
}
const p = Math.min(Math.max((s.playhead - act.start) / act.dur, 0), 1);
push(left + p * box, bottom + easeFn(p) * box, 15, 15, 0, 1, 0, u.u_c1, 1);

// Timeline: a track, the played part, a tick per act, the playhead.
const barL = left + box + 70, barR = W / 2 - 70, barY = bottom, span = barR - barL;
const at = (ms) => barL + Math.min(ms / s.total, 1) * span;
push((barL + barR) / 2, barY, span, 3, 0, 1, 0, ink, 0.16);
push((barL + at(s.playhead)) / 2, barY, at(s.playhead) - barL, 3, 0, 1, 0, ink, 0.7);
s.acts.forEach((a, i) => push(at(a.start), barY, 9, 9, 0, 1, i === actIndex ? 0 : 1, i <= actIndex ? ink : [0.5, 0.5, 0.55], 1));
push(at(s.playhead), barY, 14, 14, 0, 1, 0, u.u_c1, 1);

gl.clearColor(u.u_background[0], u.u_background[1], u.u_background[2], 1);
gl.clear(gl.COLOR_BUFFER_BIT);
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
gl.useProgram(s.program);
ctx.utils.setUniforms(s.program, { u_view: [W, H] });
gl.bindVertexArray(s.vao);
gl.bindBuffer(gl.ARRAY_BUFFER, s.buffer);
gl.bufferData(gl.ARRAY_BUFFER, s.data.subarray(0, n * s.FLOATS), gl.DYNAMIC_DRAW);
gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, n);
gl.bindVertexArray(null);

// Labels: redraw the text canvas only when the act, easing or canvas size changes.
const labelKey = `${actIndex}|${easeName}|${w}x${h}|${ink.join()}`;
if (labelKey !== s.labelKey) {
  s.labelKey = labelKey;
  const c = s.label2d ??= s.label.getContext("2d");
  s.label.width = w; s.label.height = h;
  const px = h / H, toX = (x) => (x + W / 2) * px, toY = (y) => (H / 2 - y) * px;
  const css = `rgb(${ink.map((v) => Math.round(v * 255)).join(",")})`;
  c.clearRect(0, 0, w, h);
  c.fillStyle = css; c.textBaseline = "alphabetic";
  c.font = `600 ${Math.round(22 * px)}px ui-sans-serif, system-ui, -apple-system, "Helvetica Neue", sans-serif`;
  c.fillText(`${String(actIndex + 1).padStart(2, "0")}  ${act.name.toUpperCase()}`, toX(barL), toY(barY + 26));
  c.globalAlpha = 0.6;
  c.font = `500 ${Math.round(17 * px)}px ui-monospace, "SF Mono", Menlo, monospace`;
  c.textAlign = "right";
  c.fillText(`/ ${String(s.acts.length).padStart(2, "0")}`, toX(barR), toY(barY + 26));
  c.textAlign = "left";
  c.fillText(easeName, toX(left), toY(bottom + box + 46));
  c.globalAlpha = 1;
  gl.bindTexture(gl.TEXTURE_2D, s.textTex);
  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, s.label);
  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
}
gl.useProgram(s.textProgram);
ctx.utils.bindTexture(s.textProgram, "u_text", s.textTex, 0);
ctx.utils.drawFullscreen(s.textProgram);
gl.disable(gl.BLEND);

ctx.publish("act", `${actIndex + 1}/${s.acts.length} ${act.name}`);
ctx.publish("easing", easeName);
